		@Override
		public NativeProbe newProbe() {
			return new NativeProbe() {
				private final LmdbReferenceNodeLocator.SearchContext searchContext = new LmdbReferenceNodeLocator.SearchContext();
				private final LmdbDirectAdjacencyIterator retainedDirect = new LmdbDirectAdjacencyIterator();
				private LmdbRecordIterator retained;
				private RecordIterator currentDirect;
				private LmdbDirectNativeAdjacency ownedAdjacencies;
				private boolean servedDirect;
				private boolean closed;

				@Override
				public RecordIterator open(long subj, long pred, long obj, long context) throws IOException {
					return open(subj, pred, obj, context, null);
				}

				@Override
				public RecordIterator open(long subj, long pred, long obj, long context,
						AdjacencyAccessObserver observer) throws IOException {
					if (closed) {
						throw new SailException("Probe has been closed");
					}
					checkOpen();
					try {
						closeCurrentDirect();
						servedDirect = false;
						if (!hasStatementsInSource()) {
							return EmptyRecordIterator.INSTANCE;
						}
						RecordIterator direct = tryDirect(null, subj, pred, obj, context, searchContext,
								retainedDirect, observer);
						if (direct != null) {
							currentDirect = direct;
							servedDirect = true;
							return direct;
						}
						if (retained == null) {
							retained = tripleStore.getTriplesRetained(txn, subj, pred, obj, context, explicit);
						} else {
							tripleStore.resetTriples(retained, subj, pred, obj, context, explicit);
						}
						return retained;
					} catch (RuntimeException | Error | IOException failure) {
						close();
						throw failure;
					}
				}

				private void closeCurrentDirect() {
					RecordIterator direct = currentDirect;
					currentDirect = null;
					if (direct != null) {
						direct.close();
					}
				}

				@Override
				public boolean adjacencyCacheBacked() {
					return servedDirect;
				}

				@Override
				public NativeLmdbQuerySource.NativeAdjacency adjacency(long predicate, boolean bySubject)
						throws IOException {
					return adjacency(predicate, bySubject, null);
				}

				@Override
				public NativeLmdbQuerySource.NativeAdjacency adjacency(long predicate, boolean bySubject,
						AdjacencyAccessObserver observer) throws IOException {
					checkOpen();
					if (!hasStatementsInSource()) {
						observeAdjacency(observer, false, "EMPTY_SOURCE[no statements]", predicate, bySubject);
						return null;
					}
					LmdbAdjacencyReadView view = exactAdjacencyView(false);
					if (view == null) {
						observeAdjacency(observer, false, parallelAdjacencyUnavailableReason(), predicate, bySubject);
						return null;
					}
					NativeLmdbQuerySource.NativeAdjacency result = directAdjacency.adjacency(view, predicate,
							bySubject, explicit, observer);
					if (result instanceof LmdbDirectNativeAdjacency direct) {
						ownedAdjacencies = direct.attachToProbe(ownedAdjacencies);
					}
					return result;
				}

				@Override
				public NativeLmdbQuerySource.NodePredicates nodePredicates(boolean bySubject) throws IOException {
					checkOpen();
					LmdbAdjacencyReadView view = variablePredicateView();
					return view == null ? null
							: directAdjacency.bindNodePredicates(view, bySubject, explicit, null);
				}

				@Override
				public NativeLmdbQuerySource.DynamicAdjacency dynamicAdjacency(boolean bySubject) throws IOException {
					checkOpen();
					LmdbAdjacencyReadView view = variablePredicateView();
					return view == null ? null
							: directAdjacency.bindDynamicAdjacency(view, bySubject, explicit, null);
				}

				private LmdbAdjacencyReadView variablePredicateView() throws IOException {
					return !hasStatementsInSource() || directAdjacency == null ? null : exactAdjacencyView(false);
				}

				private void observeAdjacency(AdjacencyAccessObserver observer, boolean used, String reason,
						long predicate, boolean bySubject) {
					if (observer != null) {
						observer.access(used, reason, bySubject ? StatementOrder.S : StatementOrder.O,
								NativeLmdbQuerySource.UNKNOWN_ID, predicate, NativeLmdbQuerySource.UNKNOWN_ID,
								NativeLmdbQuerySource.UNKNOWN_ID);
					}
				}

				@Override
				public void close() {
					if (closed) {
						return;
					}
					closed = true;
					servedDirect = false;
					Throwable failure = null;
					try {
						closeCurrentDirect();
					} catch (RuntimeException | Error problem) {
						failure = problem;
					}
					try {
						if (retained != null) {
							retained.dispose();
						}
					} catch (RuntimeException | Error problem) {
						if (failure == null) {
							failure = problem;
						} else if (failure != problem) {
							failure.addSuppressed(problem);
						}
					} finally {
						retained = null;
					}
					failure = closeProbeAdjacencies(ownedAdjacencies, failure);
					ownedAdjacencies = null;
					try {
						searchContext.close();
					} catch (RuntimeException | Error problem) {
						if (failure == null) {
							failure = problem;
						} else if (failure != problem) {
							failure.addSuppressed(problem);
						}
					}
					rethrowProbeCloseFailure(failure);
				}
			};
		}

