		@Override
		public NativeProbe newProbe() {
			return new RetainedNativeProbe();
		}

		/**
		 * Operator-owned probe: one dataset read stamp for the probe's lifetime (instead of one per scan) and one
		 * retained LmdbRecordIterator that is re-aimed per probe key instead of re-created. A direct iterator is
		 * retained only until the next open or probe close, matching {@link NativeProbe}'s ownership contract. The
		 * source-open check runs once per open(), the same granularity the batched wrapper already reduced it to.
		 */
		private final class RetainedNativeProbe implements NativeProbe {
			private final LmdbReferenceNodeLocator.SearchContext searchContext = new LmdbReferenceNodeLocator.SearchContext();
			private final LmdbDirectAdjacencyIterator retainedDirect = new LmdbDirectAdjacencyIterator();
			private long readStamp;
			private boolean stampHeld;
			private LmdbRecordIterator retained;
			private RecordIterator currentDirect;
			private LmdbDirectNativeAdjacency ownedAdjacencies;
			private boolean closed;
			private boolean servedDirect;
			private long adjacencyDomainPredicate;

			@Override
			public RecordIterator open(long subj, long pred, long obj, long context) throws IOException {
				return open(subj, pred, obj, context, null);
			}

			@Override
			public RecordIterator open(long subj, long pred, long obj, long context,
					AdjacencyAccessObserver observer) throws IOException {
				if (closed) {
					throw new SailException("Probe has been closed");
				}
				try {
					closeCurrentDirect();
					servedDirect = false;
					// The predicate-wide outgoing domain is a safe semijoin superset for every context selection.
					// Incoming domains deliberately decline because inlined-object keys live in a separate index.
					adjacencyDomainPredicate = subj > 0 && obj <= 0 && pred > 0 ? pred : 0L;
					if (!stampHeld) {
						readStamp = acquireNativeSourceReadLock();
						stampHeld = true;
					}
					assertNativeSourceOpen();
					if (!hasStatementsInSource()) {
						return EmptyRecordIterator.INSTANCE;
					}
					RecordIterator direct = tryDirect(null, subj, pred, obj, context, searchContext, retainedDirect,
							observer);
					if (direct != null) {
						currentDirect = direct;
						servedDirect = true;
						return direct;
					}
					if (retained == null) {
						retained = tripleStore.getTriplesRetained(txn, subj, pred, obj, context, explicit);
					} else {
						tripleStore.resetTriples(retained, subj, pred, obj, context, explicit);
					}
					return retained;
				} catch (RuntimeException | Error | IOException e) {
					close();
					throw e;
				}
			}

			private void closeCurrentDirect() {
				RecordIterator direct = currentDirect;
				currentDirect = null;
				if (direct != null) {
					direct.close();
				}
			}

			@Override
			public boolean adjacencyCacheBacked() {
				return servedDirect;
			}

			@Override
			public LmdbNativeIdDomain adjacencyCacheKeyDomain() throws IOException {
				if (adjacencyDomainPredicate <= 0) {
					return null;
				}
				return LmdbNativeIdDomain.adjacencyKeys(adjacency(adjacencyDomainPredicate, true));
			}

			@Override
			public NativeLmdbQuerySource.NativeAdjacency adjacency(long predicate, boolean bySubject)
					throws IOException {
				return adjacency(predicate, bySubject, null);
			}

			@Override
			public NativeLmdbQuerySource.NativeAdjacency adjacency(long predicate, boolean bySubject,
					AdjacencyAccessObserver observer) throws IOException {
				if (closed) {
					throw new SailException("Probe has been closed");
				}
				if (!stampHeld) {
					readStamp = acquireNativeSourceReadLock();
					stampHeld = true;
				}
				try {
					assertNativeSourceOpen();
					if (!hasStatementsInSource()) {
						observeAdjacency(observer, false, "EMPTY_SOURCE[no statements]", predicate, bySubject);
						return null;
					}
					if (directEligible()) {
						NativeLmdbQuerySource.NativeAdjacency result = directAdjacency.adjacency(adjacencyView,
								predicate, bySubject, explicit, observer);
						if (result instanceof LmdbDirectNativeAdjacency direct) {
							ownedAdjacencies = direct.attachToProbe(ownedAdjacencies);
						}
						return result;
					}
					observeAdjacency(observer, false, adjacencyUnavailableReason(), predicate, bySubject);
					return null;
				} catch (RuntimeException | Error failure) {
					close();
					throw failure;
				}
			}

			@Override
			public NativeLmdbQuerySource.NodePredicates nodePredicates(boolean bySubject) throws IOException {
				return variablePredicateEligible()
						? directAdjacency.bindNodePredicates(adjacencyView, bySubject, explicit, null)
						: null;
			}

			@Override
			public NativeLmdbQuerySource.DynamicAdjacency dynamicAdjacency(boolean bySubject) throws IOException {
				return variablePredicateEligible()
						? directAdjacency.bindDynamicAdjacency(adjacencyView, bySubject, explicit, null)
						: null;
			}

			/**
			 * Same gate the fixed-predicate view uses, hoisted so both variable-predicate views observe it. The read
			 * stamp is taken here for the same reason it is taken there: the view must stay valid for this probe's
			 * lifetime, and each parallel worker owns its own probe.
			 */
			private boolean variablePredicateEligible() throws IOException {
				if (closed) {
					throw new SailException("Probe has been closed");
				}
				if (!stampHeld) {
					readStamp = acquireNativeSourceReadLock();
					stampHeld = true;
				}
				try {
					assertNativeSourceOpen();
					return hasStatementsInSource() && directEligible();
				} catch (RuntimeException | Error failure) {
					close();
					throw failure;
				}
			}

			private String adjacencyUnavailableReason() {
				return directAdjacencyUnavailableReason();
			}

			private void observeAdjacency(AdjacencyAccessObserver observer, boolean used, String reason,
					long predicate, boolean bySubject) {
				if (observer != null) {
					observer.access(used, reason, bySubject ? StatementOrder.S : StatementOrder.O,
							NativeLmdbQuerySource.UNKNOWN_ID, predicate, NativeLmdbQuerySource.UNKNOWN_ID,
							NativeLmdbQuerySource.UNKNOWN_ID);
				}
			}

			@Override
			public void close() {
				if (closed) {
					return;
				}
				closed = true;
				servedDirect = false;
				adjacencyDomainPredicate = 0L;
				Throwable failure = null;
				try {
					closeCurrentDirect();
				} catch (RuntimeException | Error problem) {
					failure = problem;
				}
				try {
					if (retained != null) {
						retained.dispose();
					}
				} catch (RuntimeException | Error problem) {
					if (failure == null) {
						failure = problem;
					} else if (failure != problem) {
						failure.addSuppressed(problem);
					}
				} finally {
					retained = null;
				}
				failure = closeProbeAdjacencies(ownedAdjacencies, failure);
				ownedAdjacencies = null;
				try {
					searchContext.close();
				} catch (RuntimeException | Error problem) {
					if (failure == null) {
						failure = problem;
					} else if (failure != problem) {
						failure.addSuppressed(problem);
					}
				}
				if (stampHeld) {
					stampHeld = false;
					try {
						nativeSourceLock.unlockRead(readStamp);
					} catch (RuntimeException | Error problem) {
						if (failure == null) {
							failure = problem;
						} else if (failure != problem) {
							failure.addSuppressed(problem);
						}
					}
				}
				rethrowProbeCloseFailure(failure);
			}
		}

		@Override
		public long count(long subj, long pred, long obj, long context) throws IOException {
			long readStamp = acquireNativeSourceReadLock();
			try {
				assertNativeSourceOpen();
				if (!hasStatementsInSource()) {
					return 0;
				}
				if (directEligible()) {
					long direct = directAdjacency.tryCount(adjacencyView, subj, pred, obj, context, explicit);
					if (direct >= 0) {
						return direct;
					}
				}
				return tripleStore.countTriples(txn, subj, pred, obj, context, explicit);
			} finally {
				nativeSourceLock.unlockRead(readStamp);
			}
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) throws IOException {
			long readStamp = acquireNativeSourceReadLock();
			try {
				assertNativeSourceOpen();
				if (!hasStatementsInSource()) {
					return false;
				}
				if (directEligible()) {
					int direct = directAdjacency.tryHas(adjacencyView, subj, pred, obj, context, explicit);
					if (direct >= 0) {
						return direct == 1;
					}
				}
				return tripleStore.hasTriples(txn, subj, pred, obj, context, explicit);
			} finally {
				nativeSourceLock.unlockRead(readStamp);
			}
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			assertNativeSourceOpen();
			if (!hasStatementsInSource()) {
				return 0D;
			}
			try {
				return tripleStore.cardinality(subj, pred, obj, context);
			} catch (IOException | RuntimeException e) {
				return Double.POSITIVE_INFINITY;
			}
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			assertNativeSourceOpen();
			if (!hasStatementsInSource()) {
				return OptionalDouble.empty();
			}
			if (directEligible() && LmdbDirectAdjacencyStore.plannerStatsEnabled()
					&& !directAdjacency.writeTransactionBlocksAdjacency()) {
				OptionalDouble exact = cachedPlannerFanOut(predicate, bySubject);
				if (exact == null) {
					exact = directAdjacency.meanFanOut(adjacencyView, predicate, bySubject, explicit);
					if (exact.isPresent()) {
						cachePlannerFanOut(predicate, bySubject, exact);
					}
				}
				if (exact.isPresent()) {
					if (!plannerStatsHitRecorded) {
						plannerStatsHitRecorded = true;
						directAdjacency.recordPlannerStatsHit();
					}
					return exact;
				}
			}
			return tripleStore.meanFanOut(predicate, bySubject, explicit);
		}

		@Override
		public OptionalDouble distinctFanOutKeys(long predicate, boolean bySubject) {
			assertNativeSourceOpen();
			return hasStatementsInSource()
					? tripleStore.distinctFanOutKeys(predicate, bySubject, explicit)
					: OptionalDouble.empty();
		}

		@Override
		public OptionalLong adjacencyKeyDomainCardinality(long predicate, boolean bySubject) {
			assertNativeSourceOpen();
			if (!hasStatementsInSource() || !directEligible()) {
				return OptionalLong.empty();
			}
			return directAdjacency.keyDomainCardinality(adjacencyView, predicate, bySubject, explicit);
		}

		private OptionalDouble cachedPlannerFanOut(long predicate, boolean bySubject) {
			LongObjectHashMap<OptionalDouble> cache = bySubject ? plannerFanOutBySubject : plannerFanOutByObject;
			return cache == null ? null : cache.get(predicate);
		}

		private void cachePlannerFanOut(long predicate, boolean bySubject, OptionalDouble fanOut) {
			LongObjectHashMap<OptionalDouble> cache = bySubject ? plannerFanOutBySubject : plannerFanOutByObject;
			if (cache == null) {
				cache = new LongObjectHashMap<>();
				if (bySubject) {
					plannerFanOutBySubject = cache;
				} else {
					plannerFanOutByObject = cache;
				}
			}
			cache.put(predicate, fanOut);
		}

		@Override
		public OptionalLong exactDegree(long predicate, long key, boolean bySubject) {
			assertNativeSourceOpen();
			if (!hasStatementsInSource()) {
				return OptionalLong.empty();
			}
			if (directEligible()) {
				OptionalLong direct = directAdjacency.exactDegree(adjacencyView, predicate, key, bySubject, explicit);
				if (direct.isPresent()) {
					return direct;
				}
			}
			return OptionalLong.empty();
		}

